import{_ as t,o as a,c as r,a3 as o}from"./chunks/framework.DQ-7HQaQ.js";const u=JSON.parse('{"title":"Build a small RAG system","description":"A bounded implementation path from permitted documents to real retrieval, generation, citations and hosted verification.","frontmatter":{"title":"Build a small RAG system","description":"A bounded implementation path from permitted documents to real retrieval, generation, citations and hosted verification."},"headers":[],"relativePath":"students/build.md","filePath":"students/build.md","lastUpdated":1794376220000}'),s={name:"students/build.md"};function n(i,e,d,l,c,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="build-one-complete-source-to-answer-path" tabindex="-1">Build one complete source-to-answer path <a class="header-anchor" href="#build-one-complete-source-to-answer-path" aria-label="Permalink to &quot;Build one complete source-to-answer path&quot;">​</a></h1><p><strong>Aim for a small, working system before adding features.</strong> Reuse your current FastAPI application, Docker/HTTPS deployment and repository when possible. Do not replace existing services or pay for a new server simply to follow a tutorial.</p><h2 id="seven-small-steps" tabindex="-1">Seven small steps <a class="header-anchor" href="#seven-small-steps" aria-label="Permalink to &quot;Seven small steps&quot;">​</a></h2><ol><li><strong>Import</strong> around five permitted short documents. Assign stable source IDs, keep originals and record versions. Verify what the importer actually stores.</li><li><strong>Prepare</strong> text and source locations. Try heading/paragraph chunks versus a fixed-size split; inspect one broken boundary. If using a graph, define entities and typed edges with source passages.</li><li><strong>Index</strong> your chosen representation. For vectors, generate real embeddings with a recorded model version and compatible question encoder. For graphs, store real sourced relationships. A keyword baseline is useful but not a substitute for your chosen architecture.</li><li><strong>Retrieve</strong> from a real question. Display the returned source/chunk IDs, passages or graph paths before asking a model to answer.</li><li><strong>Generate</strong> with an actual accessible model/provider. Pass only authorized retrieved passages as context and show the answer with links to source locations. Model text is not automatically verified by a citation.</li><li><strong>Handle insufficient evidence.</strong> Include one question the documents cannot answer. Show an honest missing-evidence response and inspect whether the model invented details.</li><li><strong>Host and verify.</strong> Put the working app behind HTTPS, keep credentials and database services private, bound public use and demonstrate persistence after a process restart. Save the revision and actual check results.</li></ol><p>Work in <strong>one issue or small change at a time</strong>. Ask AI for the smallest patch and an explanation; inspect the code, run the tests yourself, then link a commit/PR and note what changed.</p><h2 id="what-to-show-at-each-checkpoint" tabindex="-1">What to show at each checkpoint <a class="header-anchor" href="#what-to-show-at-each-checkpoint" aria-label="Permalink to &quot;What to show at each checkpoint&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Stage</th><th>Evidence to retain</th></tr></thead><tbody><tr><td>Import</td><td>Manifest, actual stored records and repeat-import result</td></tr><tr><td>Retrieval</td><td>Query, returned source IDs or graph paths and expected relevance</td></tr><tr><td>Generation</td><td>Actual prompt/context, model/provider identification and answer</td></tr><tr><td>Source support</td><td>Openable source location and a missing-evidence example</td></tr><tr><td>Hosted operation</td><td>Working HTTPS URL, database persistence, logs without secrets and chosen source revision</td></tr><tr><td>Improvement</td><td>Real peer observation, changed code/issue and retest</td></tr></tbody></table><p>For Nov 24 Build, the <a href="https://github.com/kaw393939/is373-studio/blob/main/docs/course/milestones.md" target="_blank" rel="noreferrer">course guide</a> expects a small <strong>hosted</strong> import → retrieval → chat journey. For Dec 3, strengthen persistence, repeatable setup, evaluation and references. Canvas remains authoritative.</p><h2 id="start-with-what-you-have" tabindex="-1">Start with what you have <a class="header-anchor" href="#start-with-what-you-have" aria-label="Permalink to &quot;Start with what you have&quot;">​</a></h2><p>If your existing app already has login, a dashboard or a working server, <strong>do not rewrite those parts</strong>. Add a tiny permitted corpus and inspect the import/retrieval path first. Use the <a href="./reference">optional local reference</a> for source IDs, SQLite/FTS and an Ollama-backed vector/generation exercise; it is <strong>not</strong> a hosted assignment solution or a mandatory technology choice.</p><p>If a model is unavailable, develop the import and retrieval stages against fixed expected results, but label the unfinished generation stage accurately. Never claim a mock response proves RAG. See <a href="./stuck">debugging help</a> and <a href="./check">verification</a>.</p>',11)])])}const m=t(s,[["render",n]]);export{u as __pageData,m as default};
